layers.vertex:
attribute vec3 aO; attribute float aT, aK; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){
      float u = uTime - aT, life = aK < .5 ? .13 : (aK < 1.5 ? .55 : (aK < 2.5 ? .28 : (aK < 3.5 ? .32 : .5)));
      if (u < 0. || u > life){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK;
      if (aK < .5 || aK > 1.5){
        vec4 mv = viewMatrix*vec4(aO,1.); mv.xyz += normalize(-mv.xyz)*.3;
        float S = aK < .5 ? .4 : (aK < 2.5 ? .5 : (aK < 3.5 ? .42 : .16)); mv.xy += position.xy*S; vP = position.xy*S; gl_Position = projectionMatrix*mv;
      } else {
        float S = .62; vP = position.xy*S;
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.);
      }
    }

layers.fragment:
uniform vec3 uGold, uOrange, uPoi, uBle; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float seg(vec2 p, vec2 a, vec2 b){ vec2 pa = p-a, ba = b-a; float h = clamp(dot(pa,ba)/dot(ba,ba), 0., 1.); return length(pa - ba*h); }
    void main(){
      vec2 p = vP; float lum = 0., hot = 0.;
      if (vK > 2.5){
        vec3 col; float r = length(p);
        if (vK < 3.5){
          // II Stun snap (above the head, CC space): a ring of 4 short spikes snaps shut onto the head in 80 ms, holds a beat, fades
          float t = vU/.32, k = 1. - pow(1. - clamp(vU/.08, 0., 1.), 3.), f = (vU < .033 ? 1.8 : 1.)*(1. - smoothstep(.45, 1., t));
          float R = mix(.4, .2, k), a = atan(p.y, p.x);
          float ring = exp(-pow((r - R)/.012, 2.));
          float ga = abs(mod(a + .785, 1.5708) - .785), sp = exp(-pow(ga*r/.012, 2.))*smoothstep(R + .1, R, r)*smoothstep(R - .12, R - .02, r);
          lum = (ring*.9 + sp*1.2)*f; hot = (ring*.4 + sp*.6)*f; col = mix(uOrange, uGold, .6);
        } else {
          // II Poison / Bleed mark: a small compact mark on the target (drop / short slash), pops in, then fades
          float f = (vU < .033 ? 1.8 : 1.)*(1. - smoothstep(.25, .5, vU)), g = 1. - pow(1. - clamp(vU/.06, 0., 1.), 3.);
          if (vK < 4.5){ vec2 q = p/.16/g; float d = length(vec2(q.x, (q.y + .15)*1.15)) - .5 + .35*max(q.y + .1, 0.);   // drop
            lum = smoothstep(.06, -.02, d)*.9*f; hot = smoothstep(-.1, -.3, d)*f; col = uPoi; }
          else { vec2 q = p/.16/g; float d = seg(q, vec2(-.6, .5), vec2(.6, -.5)); float w = .12*(1. - abs(q.x)/.7) + .02;
            lum = exp(-pow(d/w, 2.))*step(abs(q.x), .65)*f; hot = exp(-pow(d/(w*.3), 2.))*step(abs(q.x), .65)*f; col = uBle; }
        }
        vec3 o = col*lum + mix(col, vec3(1.), .5)*hot;
        o *= smoothstep(1., .9, r/(vK < 3.5 ? .42 : .16));
        if (max(o.r, max(o.g, o.b)) < .002) discard;
        gl_FragColor = vec4(o, 1.); return;
      }
      if (vK > 1.5){
        // rear flash (Interrupt): an asymmetric burst of rays from the stab point — long up-and-forward, short elsewhere
        float r = length(p), a = atan(p.y, p.x), t = vU/.28, f = pow(1. - t, 1.6)*(vU < .033 ? 1.7 : 1.);
        float N = 9., fa = floor(a/6.2832*N + .5), ac = fa/N*6.2832;
        float h = fract(sin(fa*37.1)*4375.5);
        float L = (.1 + .3*pow(max(0., cos(ac - .75)), 2.) + .06*h)*(1. - pow(1. - clamp(vU/.07, 0., 1.), 3.));
        float d = abs(sin(a - ac))*r, w = .014*(1. - r/max(L, .01)) + .003;
        float ray = exp(-pow(d/w, 2.))*smoothstep(L, L*.55, r)*smoothstep(.02, .06, r);
        lum += ray*f*1.2 + exp(-r*r*60.)*f*1.4; hot += ray*f*.5 + exp(-r*r*200.)*f;
        lum *= smoothstep(.5, .42, r); hot *= smoothstep(.5, .42, r);
      } else if (vK < .5){
        float t = vU/.13, L = .06 + .24*sqrt(t), f = 1. - t;
        float d = min(seg(p, vec2(-L,0.), vec2(L,0.)), seg(p, vec2(0.,-L*.5), vec2(0.,L*.5)));
        lum += exp(-pow(d/(.007 + .006*f), 2.))*f*1.2; hot += lcore(d, .003)*f*.8;
      } else {
        // Slow: a thin ring settles inward (weight), three small chevrons point to the centre, then it fades
        float t = vU/.55, f = pow(1. - smoothstep(.45, 1., t), 1.5)*smoothstep(0., .08, t);
        float R = mix(.5, .38, 1. - pow(1. - clamp(t/.3, 0., 1.), 3.)), r = length(p);
        float ring = exp(-pow((r - R)/.009, 2.));
        float ch = 0.;
        for (int i=0;i<3;i++){
          float a = float(i)*2.0944 + .5; vec2 u = vec2(cos(a), sin(a)), n = vec2(-u.y, u.x);
          vec2 q = vec2(dot(p, n), dot(p, u)) - vec2(0., R - .09);   // chevron just inside the ring, tip pointing inward
          float dv = min(seg(q, vec2(0., -.035), vec2(-.045, .025)), seg(q, vec2(0., -.035), vec2(.045, .025)));
          ch += exp(-pow(dv/.007, 2.));
        }
        lum += (ring*.9 + ch*.8)*f; hot += ring*f*.3;
      }
      vec3 outc = mix(uOrange, uGold, .6)*lum + mix(uGold, vec3(1., .96, .88), .6)*hot;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }
